def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_D = sum(1 for x in op if x == 'D')
    my_D = sum(1 for x in my if x == 'D')
    opp_C = n - opp_D

    last_my = my[-1]
    last_opp = op[-1]
    recent5 = sum(1 for x in op[-5:] if x == 'D')

    provoked_D = 0
    unprovoked_D = 0
    c_after_D = 0
    d_after_D = 0

    for i in range(1, n):
        prev_my = my[i - 1]
        cur_opp = op[i]
        if prev_my == 'D':
            if cur_opp == 'D':
                provoked_D += 1
                d_after_D += 1
            else:
                c_after_D += 1
        else:
            if cur_opp == 'D':
                unprovoked_D += 1

    if opp_C == 0:
        return 'D'

    if opp_D <= max(1, n // 10):
        if my_D == 0 and opp_D == 0 and n >= 10:
            return 'D'
        if my_D == 1 and last_my == 'D' and last_opp == 'C':
            return 'C'
        if my_D >= 1 and d_after_D == 0 and c_after_D >= 1 and last_opp == 'C':
            return 'D'

    if opp_D >= max(3, n * 3 // 5):
        if last_opp == 'C' and recent5 == 0 and unprovoked_D <= provoked_D:
            return 'C'
        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            if opp_D <= max(3, n // 4):
                return 'C'
            return 'D'
        if unprovoked_D <= 2 and opp_D <= max(3, n // 4) and opp_C >= opp_D:
            return 'C'
        return 'D'

    if unprovoked_D > provoked_D and opp_D <= max(4, n // 3) and recent5 <= 1:
        return 'D'

    return 'C'
